import{_ as n,o as h,c as i,a3 as o}from"./chunks/framework.DX_KL3e0.js";const u=JSON.parse('{"title":"Giới thiệu hệ thống","description":"","frontmatter":{},"headers":[],"relativePath":"bat-dau/gioi-thieu.md","filePath":"bat-dau/gioi-thieu.md","lastUpdated":1782143716000}'),a={name:"bat-dau/gioi-thieu.md"};function r(g,t,e,c,d,l){return h(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="gioi-thieu-he-thong" tabindex="-1">Giới thiệu hệ thống <a class="header-anchor" href="#gioi-thieu-he-thong" aria-label="Permalink to &quot;Giới thiệu hệ thống&quot;">​</a></h1><p><strong>FADO AssetFlow</strong> là hệ thống <strong>quản lý vòng đời tài sản và vận hành nội bộ doanh nghiệp</strong>, giao diện tiếng Việt, tập trung mọi nghiệp vụ thường ngày vào một nền tảng web duy nhất.</p><h2 id="he-thong-lam-đuoc-gi" tabindex="-1">Hệ thống làm được gì? <a class="header-anchor" href="#he-thong-lam-đuoc-gi" aria-label="Permalink to &quot;Hệ thống làm được gì?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nhóm nghiệp vụ</th><th>Mô tả</th></tr></thead><tbody><tr><td><strong>Quản lý tài sản</strong></td><td>Phần cứng, phần mềm, tên miền, tài khoản email; cấp phát, thu hồi, lịch sử.</td></tr><tr><td><strong>Ticket hỗ trợ</strong></td><td>Tiếp nhận và xử lý yêu cầu hỗ trợ nội bộ (IT, hành chính…).</td></tr><tr><td><strong>Công việc (Tasks)</strong></td><td>Giao việc, theo dõi tiến độ, công việc con, bình luận, tệp đính kèm.</td></tr><tr><td><strong>Đặt phòng họp</strong></td><td>Đặt lịch phòng, tránh trùng giờ, lịch sử sử dụng.</td></tr><tr><td><strong>Nhân sự (C&amp;B)</strong></td><td>Hồ sơ nhân viên, hợp đồng, nhắc gia hạn, tài liệu nhân sự.</td></tr><tr><td><strong>Nguồn nhân lực</strong></td><td>Yêu cầu tuyển dụng, kho CV (ATS), kho mô tả công việc, onboarding, offboarding.</td></tr><tr><td><strong>Chấm công &amp; nghỉ phép</strong></td><td>Điểm danh, tích hợp máy chấm công, bảng công, bù công/tăng ca, phép năm.</td></tr><tr><td><strong>Tổ chức</strong></td><td>Công ty, phòng ban, chức danh, vị trí, nhãn tổ chức.</td></tr><tr><td><strong>Tra cứu &amp; Lịch sử</strong></td><td>Tra cứu tài sản, văn bản, thông báo; nhật ký hoạt động toàn hệ thống.</td></tr></tbody></table><h2 id="kien-truc-tong-quan-cho-it" tabindex="-1">Kiến trúc tổng quan (cho IT) <a class="header-anchor" href="#kien-truc-tong-quan-cho-it" aria-label="Permalink to &quot;Kiến trúc tổng quan (cho IT)&quot;">​</a></h2><ul><li><strong>Nền tảng:</strong> Next.js (App Router) + React + TypeScript.</li><li><strong>Cơ sở dữ liệu:</strong> PostgreSQL (self-hosted).</li><li><strong>Realtime:</strong> Server-Sent Events (SSE) cho thông báo và cập nhật tức thời.</li><li><strong>Tích hợp:</strong> Telegram (thông báo), máy chấm công ZKTeco/Ronald Jack (giao thức ADMS).</li><li><strong>Truy cập:</strong> trình duyệt web tại <code>https://assetflow.fadoai.com</code>.</li></ul><h2 id="cach-dung-tai-lieu-nay" tabindex="-1">Cách dùng tài liệu này <a class="header-anchor" href="#cach-dung-tai-lieu-nay" aria-label="Permalink to &quot;Cách dùng tài liệu này&quot;">​</a></h2><ol><li><strong>Mới bắt đầu?</strong> Đọc lần lượt mục <a href="/help/bat-dau/dang-nhap.html">Bắt đầu</a>: đăng nhập → giao diện chung → phân quyền.</li><li><strong>Cần làm một việc cụ thể?</strong> Vào <a href="/help/chuc-nang/dashboard.html">Cẩm nang chức năng</a> theo đúng module.</li><li><strong>Muốn lối đi nhanh theo công việc của mình?</strong> Xem <a href="/help/vai-tro/nguoi-dung-cuoi.html">Hướng dẫn theo vai trò</a>.</li><li><strong>Gặp trục trặc?</strong> Xem <a href="/help/phu-luc/xu-ly-su-co.html">Xử lý sự cố</a> hoặc <a href="/help/phu-luc/faq.html">FAQ</a>.</li></ol>',8)])])}const p=n(a,[["render",r]]);export{u as __pageData,p as default};
